# 3.3 — các nhánh Applications and Services Logs trong bộ mẫu: Sysmon, TerminalServices-RemoteConnectionManager, PowerShell, Defender, Firewall, LiveId.
@ps Get-ChildItem mau/*.evtx | ForEach-Object { evtx-rec $_.FullName 2>$null | ConvertFrom-Json | Select-Object -First 1 kenh } | Where-Object kenh -notin 'System','Application','Security','Setup','ForwardedEvents' | Sort-Object kenh -Unique | Format-Table -AutoSize
@ps evtx-rec 'mau/2-vss_0-Microsoft-Windows-TerminalServices-RemoteConnectionManager%4Operational.evtx' 2>$null | ConvertFrom-Json | Where-Object id -eq 1149 | ForEach-Object { [pscustomobject]@{ Luc = $_.t; Id = $_.id; User = $_.data.Param1; Domain = $_.data.Param2; IPNguon = $_.data.Param3 } } | Format-Table -AutoSize
@ps evtx-rec mau/powershell-openssh-install.evtx | ConvertFrom-Json | Group-Object kenh,id | Select-Object Count,Name | Format-Table -AutoSize
@ps evtx-rec mau/powershell-openssh-install.evtx | ConvertFrom-Json | Where-Object id -eq 4104 | Select-Object -First 3 | ForEach-Object { "{0} | {1}" -f $_.t, ($_.data.ScriptBlockText -replace '\s+',' ').Substring(0,[math]::Min(110,($_.data.ScriptBlockText -replace '\s+',' ').Length)) }
@ps evtx-rec mau/defender-1116-1117.evtx | ConvertFrom-Json | ForEach-Object { [pscustomobject]@{ Luc = $_.t; Id = $_.id; Muc = $_.muc; Ten = $_.data.'Threat Name'; Tep = $_.data.Path; HanhDong = $_.data.'Action Name' } } | Format-Table -AutoSize
@ps evtx-rec mau/defender-1151.evtx | ConvertFrom-Json | Select-Object -Last 1 | ForEach-Object { $_.data.PSObject.Properties | Where-Object Name -match 'Version|RTP state|Last quick scan|AV signature age|BM state|Product status' | Select-Object Name,Value } | Format-Table -AutoSize
@ps evtx-rec mau/firewall-2004.evtx | ConvertFrom-Json | Select-Object -First 1 | ForEach-Object { $_.kenh; $_.data | Format-List RuleName,ApplicationPath,Direction,Protocol,LocalPorts,Action,ModifyingUser,ModifyingApplication }
@ps evtx-rec mau/sysmon.evtx 2>$null | ConvertFrom-Json | Group-Object id | Sort-Object Count -Descending | Select-Object Count,@{n='Id';e={$_.Name}} | Format-Table -AutoSize
